test = [[5,7,7,4]+[7]*11,[7,5,7,4]+[7]*11,[4,4,4,4]+[7]*11]+[[7]*15 for _ in range(7)]
h,w=2,3
out=[]
for r in range(10):
    row=[]
    for c in range(15):
        if test[r%h][c%w]==5:
            row.append(5 if test[(r//h)%h][(c//w)%w]==5 else 4)
        else: row.append(7)
    out.append(row)
